UPDATE online_directions SET full_desc = 'Онлайн-подготовка к школе для детей 5–7 лет. Учимся читать по слогам и целыми словами, считать, ориентироваться на листе, готовим руку к письму. Развиваем речь, внимание, память и усидчивость, чтобы первый класс начался спокойно и уверенно.' WHERE slug = 'podgotovka-k-shkole';
UPDATE online_directions SET full_desc = 'Сопровождение по программе 1–4 класса: русский язык, математика, литературное чтение и окружающий мир. Объясняем непонятные темы, закрываем пробелы и помогаем ребёнку чувствовать себя уверенно на уроках.' WHERE slug = 'nachalnaya-shkola';
UPDATE online_directions SET full_desc = 'Онлайн-занятия по русскому языку: орфография и пунктуация, разборы, развитие письменной речи, работа над ошибками. Программа строится от текущего уровня ученика и задач — от школьных контрольных до экзаменов.' WHERE slug = 'russkiy-yazyk';
UPDATE online_directions SET full_desc = 'Математика онлайн от устного счёта до алгебры и геометрии. Разбираем темы по шагам, тренируем решение задач и учим понимать, а не заучивать. Подходит для подтягивания успеваемости и подготовки к контрольным.' WHERE slug = 'matematika';
UPDATE online_directions SET full_desc = 'Английский язык онлайн для детей и школьников: лексика, грамматика, чтение и разговорная практика. Возможны занятия с русскоговорящим педагогом и с носителем языка.' WHERE slug = 'angliyskiy-yazyk';
UPDATE online_directions SET full_desc = 'Подготовка к ОГЭ онлайн: знакомимся со структурой экзамена, разбираем типовые задания, решаем тренировочные варианты и прорабатываем ошибки. Помогаем выстроить план подготовки и снизить волнение перед экзаменом.' WHERE slug = 'podgotovka-oge';
UPDATE online_directions SET full_desc = 'Подготовка к ЕГЭ онлайн для 10–11 классов: системная работа по профильным предметам, разбор заданий всех частей экзамена, тренировка на вариантах и контроль прогресса.' WHERE slug = 'podgotovka-ege';
UPDATE online_directions SET full_desc = 'Логопед онлайн: диагностика речи, постановка и автоматизация звуков, развитие связной речи, работа над дыханием и голосом. Занятия проходят по видеосвязи в игровом формате, родитель получает рекомендации для закрепления дома.' WHERE slug = 'logoped-onlayn';
UPDATE online_directions SET full_desc = 'Дефектолог онлайн: индивидуальные занятия для детей с особенностями развития. Работаем над познавательными процессами, речью и учебными навыками по индивидуальной программе, бережно и в комфортном для ребёнка темпе.' WHERE slug = 'defektolog-onlayn';
UPDATE online_directions SET full_desc = 'Коррекционно-развивающие занятия онлайн: развитие внимания, памяти, мышления, саморегуляции и мелкой моторики. Занятия строятся с учётом возраста и особенностей ребёнка.' WHERE slug = 'korrektsionnye-zanyatiya';
UPDATE online_directions SET full_desc = 'Помощь с домашними заданиями онлайн: разбираем задания вместе с педагогом, объясняем непонятные темы и учим ребёнка выполнять уроки самостоятельно.' WHERE slug = 'pomoshch-s-dz';
UPDATE online_directions SET full_desc = 'Индивидуальные онлайн-занятия по любому школьному предмету. Персональная программа, удобный темп и всё внимание педагога одному ученику.' WHERE slug = 'individualnye-zanyatiya';
UPDATE online_directions SET full_desc = 'Развивающие занятия онлайн для дошкольников и младших школьников: логика, кругозор, творчество и речь. Интересные задания без перегрузки.' WHERE slug = 'razvivayushchie-zanyatiya';

